SELECT percentile_cont(0.9) within GROUP (ORDER BY (SELECT value FROM labevents WHERE subject_id = high_risk_patients.subject_id AND charttime BETWEEN high_risk_patients.admittime AND (high_risk_patients.admittime + interval '48 hours'))) AS high_risk_percentile, COUNT(DISTINCT high_risk_patients.subject_id) AS high_risk_patient_count, SUM(CASE WHEN high_risk_patients.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS high_risk_death_count, AVG(high_risk_patients.dischtime - high_risk_patients.admittime) AS high_risk_avg_length_of_stay, SUM(CASE WHEN high_risk_patients.dischtime IS NOT NULL AND high_risk_patients.dischtime < (high_risk_patients.admittime + interval '48 hours') THEN 1 ELSE 0 END) AS high_risk_critical_lab_count, COUNT(DISTINCT stable_patients.subject_id) AS stable_patient_count, SUM(CASE WHEN stable_patients.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS stable_death_count, AVG(stable_patients.dischtime - stable_patients.admittime) AS stable_avg_length_of_stay FROM acs_patients JOIN high_risk_patients ON acs_patients.subject_id = high_risk_patients.subject_id JOIN stable_patients ON acs_patients.subject_id = stable_patients.subject_id;